#[derive(Default, Clone)]
struct Args {
    positional: Vec<String>,
    rect: Option<Rect>,
    out: Option<String>,
    timeout_ms: Option<i64>,
    max_age_ms: Option<i64>,
    frames: Option<i64>,
    interval_ms: Option<i64>,
    /// `shot diff --tolerance <f>` — the caller's MEASURED noise floor for this subject, which is the
    /// only thing that can turn the numbers into a same/changed verdict. Absent ⇒ report, do not judge.
    tolerance: Option<f64>,
    /// `baseline --kit <k>` — sweep every component of the kit instead of one named component
    /// (#a-baseline-sweep-walks-the-kit-itself).
    kit: Option<String>,
    /// `analyze --keep` — do NOT reap the capture, for when a human wants to look at the PNG.
    keep: bool,
    /// `analyze --file <path>` — read a PNG that already exists instead of capturing one. NEVER reaped:
    /// the caller's file is not ours to delete.
    file: Option<String>,
    /// `analyze --engine <e>` — which analyser reads the pixels. Named rather than hardcoded so a later
    /// engine is a new arm, not a rewrite of every caller.
    engine: Option<String>,
    json: bool,
    pretty: bool,
}

fn parse_args(args: Vec<String>) -> Result<Args, String> {
    let mut a = Args::default();
    let mut it = args.into_iter();
    while let Some(tok) = it.next() {
        match tok.as_str() {
            "--json" => a.json = true,
            "--pretty" => a.pretty = true,
            "--rect" => a.rect = Some(parse_rect(&it.next().ok_or("--rect needs x,y,w,h")?)?),
            "--out" => a.out = Some(it.next().ok_or("--out needs a path")?),
            "--kit" => a.kit = Some(it.next().ok_or("--kit needs a kit id")?),
            "--keep" => a.keep = true,
            "--file" => a.file = Some(it.next().ok_or("--file needs a path")?),
            "--engine" => a.engine = Some(it.next().ok_or("--engine needs a name")?),
            "--timeout" => {
                let v = it.next().ok_or("--timeout needs a value in ms")?;
                a.timeout_ms = Some(v.parse().map_err(|_| format!("--timeout: not a number: {v}"))?);
            }
            "--max-age" => {
                let v = it.next().ok_or("--max-age needs a value in ms")?;
                a.max_age_ms = Some(v.parse().map_err(|_| format!("--max-age: not a number: {v}"))?);
            }
            "--tolerance" => {
                let v = it.next().ok_or("--tolerance needs a number, e.g. --tolerance 0.01")?;
                a.tolerance = Some(v.parse::<f64>().map_err(|_| format!("--tolerance '{v}' is not a number"))?);
            }
            "--frames" => {
                let v = it.next().ok_or("--frames needs a count")?;
                a.frames = Some(v.parse().map_err(|_| format!("--frames: not a number: {v}"))?);
            }
            "--interval" => {
                let v = it.next().ok_or("--interval needs a value in ms")?;
                a.interval_ms = Some(v.parse().map_err(|_| format!("--interval: not a number: {v}"))?);
            }
            other if other.starts_with("--") => return Err(format!("unknown flag: {other}")),
            other => a.positional.push(other.to_string()),
        }
    }
    Ok(a)
}

/// `x,y,w,h`. A zero-area rect is rejected here rather than sent to the app to fail — the CLI can tell
/// the caller exactly what was wrong; the app could only say "capture failed".
pub fn parse_rect(s: &str) -> Result<Rect, String> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() != 4 {
        return Err(format!("--rect wants x,y,w,h (4 comma-separated numbers), got: {s}"));
    }
    let n = |i: usize| -> Result<u32, String> {
        parts[i].parse::<u32>().map_err(|_| format!("--rect: not a non-negative number: {}", parts[i]))
    };
    let (x, y, w, h) = (n(0)?, n(1)?, n(2)?, n(3)?);
    if w == 0 || h == 0 {
        return Err(format!("--rect: width and height must be > 0, got {w}x{h}"));
    }
    Ok(Rect { x, y, w, h })
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;
    let cmd = args.positional.first().cloned().unwrap_or_default();

    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }

    match cmd.as_str() {
        "take" => cmd_take(&args),
        "preview" => cmd_preview(&args),
        "frame" => cmd_frame(&args),
        "baseline" => cmd_baseline(&args),
        "analyze" => cmd_analyze(&args),
        "diff" => cmd_diff(&args),
        "pending" => cmd_pending(&args),
        "sweep" => cmd_sweep(&args),
        "dir" => cmd_dir(&args),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

/// `bsc shot take` — capture the whole webview (or an explicit `--rect`), full-screen. The full-cap
/// surface (the debug session); the designer is restricted to `preview` (#3308).
fn cmd_take(args: &Args) -> Result<(), String> {
    capture_and_emit(args, None)
}

/// `bsc shot preview` — capture JUST the Design Studio's component preview: the app resolves the "preview"
/// target's rect itself (#3308). `--rect` is meaningless here (the target IS the region), so reject it
/// rather than silently ignore. This is the designer's only shot verb.
fn cmd_preview(args: &Args) -> Result<(), String> {
    if args.rect.is_some() {
        return Err("`bsc shot preview` crops to the component preview itself — drop --rect (use `bsc shot take --rect` for a manual region)".into());
    }
    capture_and_emit(args, Some("preview"))
}

/// The `frame:` target prefix the app routes to a mounted preview by component id (#3469). Kept here
/// beside the verb that mints it so the CLI and the app agree on one spelling.
const FRAME_PREFIX: &str = "frame:";

/// `bsc shot frame <component>` — capture the mounted preview of ONE named component (#3469).
///
/// Where `preview` shoots whatever the Studio is showing, this names the SUBJECT: the app resolves the
/// rect from its mounted previews, so a session chooses what to photograph rather than depending on
/// what the user last clicked. Like `preview`, `--rect` is meaningless (the frame IS the region) and is
/// rejected rather than silently ignored.
fn cmd_frame(args: &Args) -> Result<(), String> {
    if args.rect.is_some() {
        return Err("`bsc shot frame` crops to the named component's preview — drop --rect (use `bsc shot take --rect` for a manual region)".into());
    }
    let component = args.positional.get(1).map(String::as_str).unwrap_or_default();
    if component.is_empty() {
        return Err("`bsc shot frame` needs a component: `bsc shot frame <component>` (see `bsc shot frame help`)".into());
    }
    capture_and_emit(args, Some(&format!("{FRAME_PREFIX}{component}")))
}


/// The first line of a multi-line error — a sweep report stays one line per component, and the detail
/// is still reachable by re-running that single component.
fn first_line(e: &str) -> String {
    e.lines().next().unwrap_or(e).trim().to_string()
}

/// One component's outcome in a `baseline --kit` sweep. A sweep that reported only successes would be
/// worse than none: the designer's whole reason for baselines is to trust them afterwards, and a
/// silently-missing one turns into a `diff` that cannot run — or a comparison against a stale reference.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct SweepOutcome {
    id: String,
    /// `captured` | `skipped`
    status: &'static str,
    /// Why it was skipped. Empty when captured.
    #[serde(skip_serializing_if = "str::is_empty")]
    reason: String,
}

/// Every component id in `kit`, read straight from the component store. Sorted, so a sweep and its
/// report are stable across runs.
fn kit_component_ids(kit: &str) -> Result<Vec<String>, String> {
    let store = bsc_json_store::Store::open_default("components", "component")?;
    let mut ids: Vec<String> = store
        .list()
        .iter()
        .filter_map(|j| serde_json::from_str::<serde_json::Value>(j).ok())
        .filter(|v| v.get("kitId").and_then(|k| k.as_str()) == Some(kit))
        // A suppression tombstone occupies an id but has no component to render (#3725).
        .filter(|v| v.get("suppressed").and_then(serde_json::Value::as_bool) != Some(true))
        .filter_map(|v| v.get("id").and_then(|i| i.as_str()).map(str::to_string))
        .collect();
    ids.sort();
    Ok(ids)
}

/// `baseline <component>` / `baseline list` (#a-shot-baseline-is-a-named-reference-render) — capture the
/// mounted preview and keep it as that component's NAMED reference.
///
/// It is a thin wrapper on `frame`: same subject resolution, same not-mounted error, only the
/// destination differs. The value is not the capture, it is that the path stops being the caller's to
/// remember — a 45-component sweep otherwise offers 45 chances to diff the wrong pair, and a wrong pair
/// fails SILENTLY with a plausible number about two images nobody meant to compare.
fn cmd_baseline(args: &Args) -> Result<(), String> {
    let arg = args.positional.get(1).map(String::as_str).unwrap_or_default();
    if arg == "list" {
        let dir = baseline_path(&shots_dir()?, "x")
            .parent()
            .map(std::path::Path::to_path_buf)
            .unwrap_or_default();
        let mut ids: Vec<String> = std::fs::read_dir(&dir)
            .into_iter()
            .flatten()
            .flatten()
            .filter_map(|e| {
                let n = e.file_name().to_string_lossy().into_owned();
                n.strip_suffix(".png").map(str::to_string)
            })
            .collect();
        ids.sort();
        bsc_cli_util::emit(args.pretty, args.json, &ids, || {
            if ids.is_empty() {
                "no baselines yet — `bsc shot baseline <component>` saves one".to_string()
            } else {
                ids.join("
")
            }
        });
        return Ok(());
    }
    // THE SWEEP (#a-baseline-sweep-walks-the-kit-itself). Lands each component itself, because the actor
    // that needs this — a designer session under `restrictedAllow` — cannot compose two commands in a
    // shell loop. Its auto-runnable surface is its grant list, and bash is not on it.
    if let Some(kit) = args.kit.clone() {
        if !arg.is_empty() {
            // Refused rather than silently preferring one: a caller who passed both means something we
            // cannot know, and guessing would capture the wrong set without saying so.
            return Err(format!(
                "`bsc shot baseline` takes a component OR --kit, not both (got '{arg}' and --kit {kit})"
            ));
        }
        let ids = kit_component_ids(&kit)?;
        if ids.is_empty() {
            return Err(format!("no components in kit '{kit}' — check `bsc ui list --kit {kit}`"));
        }
        let timeout = args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS);
        let shots = shots_dir()?;
        let mut out: Vec<SweepOutcome> = Vec::new();
        for id in ids {
            // ONE FAILURE DOES NOT ABORT THE SWEEP. A kit where three components fail is still 42
            // baselines the designer did not have to take by hand — and the three are named at the end.
            match bsc_navigate::cli::navigate_component(&kit, &id, timeout) {
                Err(e) => {
                    out.push(SweepOutcome { id, status: "skipped", reason: first_line(&e) });
                    continue;
                }
                Ok(view) => {
                    // The ack reports what actually MOUNTED. A declined steer (the presence gate, #4248 —
                    // someone is using the app) answers without the component, and capturing then would
                    // photograph whatever is on screen under this component's name. That is the failure
                    // a baseline must never make.
                    if view.component.as_deref() != Some(id.as_str()) {
                        out.push(SweepOutcome {
                            id,
                            status: "skipped",
                            reason: "the app did not land it (a steer is declined while someone is using the app)".into(),
                        });
                        continue;
                    }
                }
            }
            let dest = baseline_path(&shots, &id);
            if let Some(parent) = dest.parent() {
                std::fs::create_dir_all(parent).map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
            }
            let mut a = args.clone();
            a.out = Some(dest.to_string_lossy().into_owned());
            a.json = false;
            a.pretty = false;
            match capture_and_emit(&a, Some(&format!("{FRAME_PREFIX}{id}"))) {
                Ok(()) => out.push(SweepOutcome { id, status: "captured", reason: String::new() }),
                Err(e) => out.push(SweepOutcome { id, status: "skipped", reason: first_line(&e) }),
            }
        }
        let captured = out.iter().filter(|o| o.status == "captured").count();
        let skipped = out.len() - captured;
        bsc_cli_util::emit(args.pretty, args.json, &out, || {
            let mut lines = vec![format!("{captured} captured, {skipped} skipped — kit {kit}")];
            for o in out.iter().filter(|o| o.status == "skipped") {
                lines.push(format!("  skipped {}: {}", o.id, o.reason));
            }
            lines.join("
")
        });
        return Ok(());
    }
    if arg.is_empty() {
        return Err("`bsc shot baseline` needs a component: `bsc shot baseline <component>` (or `--kit <k>`, or `baseline list`)".into());
    }
    if args.out.is_some() {
        return Err("`bsc shot baseline` owns its destination — drop --out (use `bsc shot frame --out` for an arbitrary path)".into());
    }
    let dest = baseline_path(&shots_dir()?, arg);
    if let Some(parent) = dest.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
    }
    // Reuse the frame path wholesale — `run_capture` resolves the subject, enforces the mounted check and
    // writes the PNG; only `out` is ours.
    let mut a = args.clone();
    a.out = Some(dest.to_string_lossy().into_owned());
    capture_and_emit(&a, Some(&format!("{FRAME_PREFIX}{arg}")))
}

/// The only analyser today. Named rather than assumed so `--engine` has something to reject against, and
/// so a later local-VLM arm is an addition instead of a rewrite of every caller.
const DEFAULT_ENGINE: &str = "pixels";

/// `bsc shot analyze [<component>]` — capture, analyse, reap.
///
/// The reason this verb exists rather than a `--reap` flag on `take`: an immediate reap is only possible
/// when the thing that READS the capture is in the same invocation that made it. `take` hands a path to
/// a separate process and cannot know whether it was ever read, so it can only bound the directory. Here
/// the analysis happens before the command returns, so the pixels never need a lifetime at all.
fn cmd_analyze(args: &Args) -> Result<(), String> {
    if args.frames.is_some_and(|n| n != 1) {
        return Err("`bsc shot analyze` reads ONE frame — drop --frames (use `bsc shot frame --frames` for a burst)".into());
    }
    let engine = args.engine.as_deref().unwrap_or(DEFAULT_ENGINE);
    if engine != DEFAULT_ENGINE {
        return Err(format!("unknown --engine '{engine}' — have: {DEFAULT_ENGINE}"));
    }
    let component = args.positional.get(1).map(String::as_str).unwrap_or_default();

    // `--file` reads a PNG that already exists. It is NEVER reaped — the reap is only ever justified
    // because the capture was ours and transient, and deleting a file the caller handed us would be a
    // destructive surprise for a verb whose whole job is reading. `ours` carries exactly that.
    let (path, ours) = match args.file.as_deref() {
        Some(f) => {
            if !component.is_empty() {
                return Err(format!("`--file` reads {f} — drop the '{component}' positional, which asks for a capture instead"));
            }
            if args.rect.is_some() {
                return Err("`--rect` crops a CAPTURE — it cannot re-crop an existing --file".into());
            }
            (f.to_string(), false)
        }
        None => {
            let target = (!component.is_empty()).then(|| format!("{FRAME_PREFIX}{component}"));
            let results = run_capture(args, target.as_deref())?;
            (results.into_iter().next().ok_or("the capture produced no frame")?.path, true)
        }
    };

    let (frame, kept) = analyze_captured(&path, args.keep || !ours)?;

    let fate = match (&kept, ours) {
        (None, _) => "reaped".to_string(),
        // Distinguished on purpose: "kept" means a capture we made and did not reap; "read" means a file
        // that was never ours. Collapsing them would imply this verb had considered deleting the latter.
        (Some(p), true) => format!("kept: {p}"),
        (Some(p), false) => format!("read: {p}"),
    };
    let payload = serde_json::json!({
        "engine": engine,
        "source": if ours { "capture" } else { "file" },
        "frame": frame,
        "kept": kept,
    });
    bsc_cli_util::emit(args.pretty, args.json, &payload, || analyze_line(&frame, &fate));
    Ok(())
}

/// Everything after the capture: read the pixels, reap, report.
///
/// Split from [`cmd_analyze`] so the ORDER is provable without a live app — the reap happens BEFORE the
/// read's result is propagated, so a capture that could not be analysed still cleans up after itself.
/// That is the case where leftovers pile up unnoticed, because nobody goes looking at the output of a
/// command that failed.
fn analyze_captured(path: &str, keep: bool) -> Result<(crate::Frame, Option<String>), String> {
    let verdict = crate::compare::load(std::path::Path::new(path))
        .map(|img| crate::analyze_frame(img.w, img.h, &img.px));
    // Deliberately before the `?`. `reap` returning false (a baseline, or a removal that failed) reads
    // the same as `--keep`: the file is still there, so say where.
    let kept = (keep || !reap(path)).then(|| path.to_string());
    Ok((verdict?, kept))
}

/// Delete a capture. Returns whether it actually went.
///
/// REFUSES anything under `<shots>/baselines/`, whatever put it there — a `--out` aimed into that
/// directory would otherwise let `analyze` eat a stored reference render, and every later `diff` would
/// then report a plausible number about nothing. Structural, matching how the retention window reaches
/// only the top level.
///
/// A removal that fails is not an error: the analysis already succeeded, and the window still bounds the
/// directory, so the worst case is one extra file rather than a leak.
fn reap(path: &str) -> bool {
    let p = std::path::Path::new(path);
    if p.parent().and_then(|d| d.file_name()).is_some_and(|n| n == "baselines") {
        return false;
    }
    std::fs::remove_file(p).is_ok()
}

/// The lean one-line verdict. `blank` leads, loudly, because it is the finding that invalidates
/// everything else on the line.
fn analyze_line(f: &crate::Frame, fate: &str) -> String {
    let [r, g, b] = f.background;
    let head = if f.blank { "BLANK — nothing rendered · " } else { "" };
    format!(
        "{head}{}x{} · {} colours · bg #{r:02x}{g:02x}{b:02x} · ink {:.1}% · {}/{} tiles empty · {fate}",
        f.w,
        f.h,
        f.colours,
        f.ink * 100.0,
        f.empty_tiles,
        f.tiles,
    )
}

/// `diff <baseline.png> <current.png>` — compare two captures; scalars only.
fn cmd_diff(args: &Args) -> Result<(), String> {
    let base = args.positional.get(1).map(String::as_str).unwrap_or_default();
    let cur = args.positional.get(2).map(String::as_str).unwrap_or_default();
    // THE ID FORM (#a-shot-baseline-is-a-named-reference-render): one positional that is not a path names
    // a COMPONENT — compare its saved baseline against `frame`'s default output for the same id. Pure
    // sugar over the two-path form below, which is the older contract and stays byte-identical.
    let (base, cur) = if cur.is_empty() && !base.is_empty() && !looks_like_a_path(base) {
        let shots = shots_dir()?;
        let saved = baseline_path(&shots, base);
        if !saved.is_file() {
            // A verdict against a baseline that does not exist would be a number about nothing. Say what
            // is missing and how to make it, rather than reporting `changed` on an absence.
            return Err(format!(
                "no baseline for '{base}' — capture one first:
  bsc navigate component <kit> {base}
  bsc shot baseline {base}"
            ));
        }
        let current = shots.join(format!("{base}.png"));
        if !current.is_file() {
            return Err(format!(
                "no current capture for '{base}' at {} — take one with `bsc shot frame {base}`",
                current.display()
            ));
        }
        (saved.to_string_lossy().into_owned(), current.to_string_lossy().into_owned())
    } else {
        (base.to_string(), cur.to_string())
    };
    let (base, cur) = (base.as_str(), cur.as_str());
    if base.is_empty() || cur.is_empty() {
        return Err("usage: bsc shot diff <baseline.png> <current.png> [--tolerance <f>]   (or `bsc shot diff <component>`)".into());
    }
    let a = crate::compare::load(std::path::Path::new(base))?;
    let b = crate::compare::load(std::path::Path::new(cur))?;
    match crate::compare::compare(&a, &b) {
        // A size change is a RESULT, not a failure — and the loudest one available, so it is reported in
        // the same shape rather than as an error string a caller has to parse.
        Err(crate::compare::Mismatch::Dimensions { baseline, current }) => {
            let v = serde_json::json!({
                "mismatch": "dimensions", "baseline": baseline, "current": current,
                "verdict": "changed",
            });
            bsc_cli_util::emit(args.pretty, args.json, &v, || {
                format!(
                    "changed — dimensions differ: baseline {}x{}, current {}x{} (the layout moved)",
                    baseline[0], baseline[1], current[0], current[1]
                )
            });
            Ok(())
        }
        Ok(d) => {
            // The verdict is only rendered when the caller supplied a tolerance IT measured. Absent one,
            // this reports and says nothing about same/changed — a default constant here would be a guess
            // presented as a measurement.
            let verdict = args.tolerance.map(|t| if d.worst_tile <= t { "same" } else { "changed" });
            let mut v = serde_json::to_value(&d).map_err(|e| e.to_string())?;
            if let (Some(o), Some(verd)) = (v.as_object_mut(), verdict) {
                o.insert("verdict".into(), serde_json::Value::String(verd.into()));
            }
            bsc_cli_util::emit(args.pretty, args.json, &v, || {
                format!(
                    "{}distance {:.5} · worst tile {:.5} at [{},{}] · {:.1}% of pixels differ",
                    verdict.map(|x| format!("{x} — ")).unwrap_or_default(),
                    d.distance, d.worst_tile, d.tile[0], d.tile[1], d.changed_fraction * 100.0
                )
            });
            Ok(())
        }
    }
}

/// The shared capture path for `take`/`preview`: one frame, or a `--frames` burst. `target` is `None` for
/// the whole webview (`take`) or `Some("preview")` for the app-resolved component-preview crop.
fn run_capture(args: &Args, target: Option<&str>) -> Result<Vec<ShotResult>, String> {
    let chan = bsc_appchan::chan_dir()?;
    let now = bsc_util::now_ms();
    let _ = bsc_appchan::sweep_stale(&chan, now, STALE_MS); // best-effort: never block a capture

    let frames = args.frames.unwrap_or(1);
    if !(1..=MAX_FRAMES).contains(&frames) {
        return Err(format!("--frames must be between 1 and {MAX_FRAMES}, got {frames}"));
    }
    let timeout = args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS);

    // Single frame: the original behavior + output (a bare path, or { path, w, h }).
    if frames == 1 {
        let shots = shots_dir()?;
        let id = bsc_appchan::new_id(now);
        // Resolve the PNG path HERE — in the session env, honoring $BSC_SHOT_DIR (#3662). The app has
        // NO $BSC_SHOT_DIR, so leaving `out` unset let it default to the GLOBAL shots dir, outside the
        // studio session's confined workspace — every capture became unreadable to the caller.
        let out = resolve_out(args.out.as_deref(), &shots, &id);
        let res = capture_one(&chan, &id, now, args.rect, Some(out), target, timeout)?;
        return Ok(vec![res]);
    }

    // Burst: N single captures spaced by --interval. One base id ties the set together; each frame gets a
    // zero-padded -NN. Each frame round-trips the channel, so the REAL gap is max(--interval, round-trip).
    let interval = args.interval_ms.unwrap_or(DEFAULT_INTERVAL_MS).max(0) as u64;
    let base_id = bsc_appchan::new_id(now);
    let pad = frames.to_string().len().max(2);
    let shots = shots_dir()?;
    let mut results: Vec<ShotResult> = Vec::with_capacity(frames as usize);
    for i in 1..=frames {
        let n = i as usize;
        let id = format!("{base_id}-{n:0pad$}");
        // Number the burst frame, then resolve against the SESSION shots dir (#3662) so a relative
        // --out lands inside the workspace, not the app's cwd.
        let out = resolve_out(
            args.out.as_deref().map(|base| insert_suffix(base, n, pad)).as_deref(),
            &shots,
            &id,
        );
        match capture_one(&chan, &id, bsc_util::now_ms(), args.rect, Some(out), target, timeout) {
            Ok(res) => results.push(res),
            // Keep the frames already captured — a partial burst is still useful; report how many landed.
            Err(e) => {
                let done = results.iter().map(|r| r.path.as_str()).collect::<Vec<_>>().join("\n  ");
                return Err(format!(
                    "frame {i}/{frames} failed: {e}\ncaptured {} frame(s) first:\n  {done}",
                    results.len()
                ));
            }
        }
        if i < frames {
            std::thread::sleep(std::time::Duration::from_millis(interval));
        }
    }

    Ok(results)
}

/// Print what a capture verb has always printed. Split out of [`run_capture`] so `analyze` can take the
/// PATH without also emitting it — the refactor `baseline` needs for the same reason.
///
/// The single/burst shapes are kept byte-identical: exactly one result IS the single-frame case, since a
/// burst that loses a frame returns `Err` with the ones already captured rather than a short `Ok`.
fn emit_capture(args: &Args, results: &[ShotResult]) {
    match results {
        [one] => bsc_cli_util::emit(args.pretty, args.json, one, || one.path.clone()),
        many => {
            let plain = many.iter().map(|r| r.path.clone()).collect::<Vec<_>>().join("\n");
            let payload = serde_json::json!({ "frames": many });
            bsc_cli_util::emit(args.pretty, args.json, &payload, || plain.clone());
        }
    }
}

/// Capture and print — what every verb but `analyze` wants.
fn capture_and_emit(args: &Args, target: Option<&str>) -> Result<(), String> {
    let results = run_capture(args, target)?;
    emit_capture(args, &results);
    Ok(())
}

/// Resolve the PNG destination IN THE CALLER'S ENV (honoring the session's `$BSC_SHOT_DIR` via
/// [`shots_dir`]) so the app writes where the CALLER expects. The app process has no `$BSC_SHOT_DIR`, so
/// a request that left `out` unset — or gave a RELATIVE `--out` — was resolved by the app against its
/// OWN (global) dir / cwd: the #3662 mismatch where `bsc shot dir` and the real PNG path disagreed and
/// every capture landed outside the studio session's confined workspace. No `--out` ⇒ `<shots>/<id>.png`;
/// a relative `--out` ⇒ inside the shots dir; an absolute `--out` ⇒ as-is.
/// Where a component's NAMED reference render lives (#a-shot-baseline-is-a-named-reference-render):
/// `<shots>/baselines/<component>.png`, under the SESSION's shots dir so `$BSC_SHOT_DIR` is honoured
/// exactly as it is for every other capture — a confined session must be able to read what it wrote.
fn baseline_path(shots: &std::path::Path, component: &str) -> std::path::PathBuf {
    shots.join("baselines").join(format!("{component}.png"))
}

/// Does this `diff` positional name a FILE, or a component id? A path is anything that ends `.png` or
/// carries a separator — everything else is an id. Deliberately narrow: the two-path form is the older
/// contract and must keep winning any ambiguity, so a real file is never re-read as an id.
fn looks_like_a_path(s: &str) -> bool {
    s.ends_with(".png") || s.contains('/') || s.contains('\\')
}

fn resolve_out(out: Option<&str>, shots: &std::path::Path, id: &str) -> String {
    match out {
        Some(o) if std::path::Path::new(o).is_absolute() => o.to_string(),
        Some(o) => shots.join(o).to_string_lossy().into_owned(),
        None => shots.join(format!("{id}.png")).to_string_lossy().into_owned(),
    }
}

/// The read-back failure, reported so it diagnoses ITSELF (#4163).
///
/// The app returns a path only AFTER a successful write, so a capture the caller then cannot read is a
/// disagreement between the two processes about where that path IS — the class #3662 closed for the
/// no-`--out` / relative-`--out` case. `the app reported <path> but it cannot be read: os error 2` named
/// none of the state that decides it: what the caller ASKED for, the `$BSC_SHOT_DIR` it resolved that
/// against, and the dir the APP resolved. A designer session lost every screenshot to this with nothing
/// in the message to act on. All four now travel with the error, and when the two dirs differ the message
/// says that is the likely cause rather than leaving it to be inferred.
/// `mine` is the caller's own `$BSC_SHOT_DIR` — passed in rather than read here so this stays a pure
/// formatter its tests can drive directly, without mutating process-global env under parallel tests.
fn unreadable_report(
    res: &ShotResult,
    requested_out: Option<&str>,
    mine: Option<&str>,
    err: &std::io::Error,
) -> String {
    let mut s = format!("the app reported {} but it cannot be read: {err}\n", res.path);
    s.push_str(&format!(
        "  you asked for:        {}\n",
        requested_out.unwrap_or("(nothing — the app picks <shots>/<id>.png)"),
    ));
    s.push_str(&format!(
        "  your $BSC_SHOT_DIR:   {}\n",
        mine.unwrap_or("(unset — the caller falls back to ~/.base-studio-code/shots)"),
    ));
    s.push_str(&format!(
        "  the app's shots dir:  {}\n",
        res.shots_dir.as_deref().unwrap_or("(not reported — the running app predates this field, #4163)"),
    ));
    // The specific, actionable diagnosis: the app resolved a DIFFERENT dir than the caller, so it wrote
    // somewhere the caller never looks. Only stated when the two are actually known to differ.
    match (res.shots_dir.as_deref(), mine) {
        (Some(theirs), Some(ours)) if !same_dir(theirs, ours) => s.push_str(
            "\nThe two dirs differ: the app resolved its own (it does not inherit this session's \
             $BSC_SHOT_DIR), so the PNG is likely under the app's dir, not yours. Pass an ABSOLUTE \
             --out to remove the ambiguity.\n",
        ),
        (Some(_), _) => s.push_str(
            "\nBoth sides agree on the dir, so the path is not the disagreement — the file was written \
             and then removed, or the app is not seeing the same filesystem as this shell (a sandboxed \
             session). `bsc shot dir` shows what this shell resolves.\n",
        ),
        _ => {}
    }
    s
}

/// Do two dir strings name the same place, allowing for separator style and a trailing slash? A textual
/// comparison would report `C:/x` and `C:\x\` as a divergence and send the reader down a false trail.
fn same_dir(a: &str, b: &str) -> bool {
    let norm = |s: &str| s.replace('\\', "/").trim_end_matches('/').to_ascii_lowercase();
    norm(a) == norm(b)
}

/// One webview snapshot: request → wait → prove the PNG is real. Shared by the single capture and each
/// burst frame. A capture that silently produced nothing (or a non-PNG) must NOT read as success — that
/// is the failure this whole surface exists to avoid.
#[allow(clippy::too_many_arguments)]
fn capture_one(
    chan: &std::path::Path,
    id: &str,
    now: i64,
    rect: Option<Rect>,
    out: Option<String>,
    target: Option<&str>,
    timeout: i64,
) -> Result<ShotResult, String> {
    let req_out = out.clone();
    let req = ShotRequest { rect, out, target: target.map(String::from) };
    bsc_appchan::write_request(chan, id, KIND, now, &req)?;
    let reply = bsc_appchan::poll_reply(chan, id, timeout, POLL_INTERVAL_MS, || {
        format!(
            "timed out after {timeout}ms waiting for the app to answer.\n\
             The request is at {}.\n\
             Is the desktop app running? `bsc` cannot capture on its own — the app's watcher does the \
             snapshot. `bsc shot pending` shows whether the request landed.",
            bsc_appchan::request_path(chan, id).display()
        )
    })?;
    let res: ShotResult = bsc_appchan::take_payload(reply).map_err(|e| format!("capture failed: {e}"))?;
    // The caller's own dir, read here (once) so the report stays a pure formatter.
    let mine = std::env::var("BSC_SHOT_DIR").ok().filter(|d| !d.trim().is_empty());
    let bytes = std::fs::read(&res.path)
        .map_err(|e| unreadable_report(&res, req_out.as_deref(), mine.as_deref(), &e))?;
    if !is_png(&bytes) {
        return Err(format!("the app wrote {} but it is not a PNG ({} bytes)", res.path, bytes.len()));
    }
    Ok(res)
}

/// Insert a zero-padded `-NN` frame marker before `path`'s file extension, or append it when there is
/// none — so `--out anim.png` becomes `anim-01.png`, `anim-02.png`, … A dot that belongs to a parent
/// directory (`C:/a.b/out`) is NOT treated as an extension.
fn insert_suffix(path: &str, n: usize, pad: usize) -> String {
    let suffix = format!("-{n:0pad$}");
    match path.rfind('.') {
        Some(dot) if dot > 0 && dot + 1 < path.len() && !path[dot..].contains(['/', '\\']) => {
            format!("{}{}{}", &path[..dot], suffix, &path[dot..])
        }
        _ => format!("{path}{suffix}"),
    }
}

fn cmd_pending(args: &Args) -> Result<(), String> {
    let chan = bsc_appchan::chan_dir()?;
    let pending = bsc_appchan::pending(&chan)?;
    bsc_cli_util::emit(args.pretty, args.json, &pending, || {
        if pending.is_empty() {
            "no pending requests".to_string()
        } else {
            pending.iter().map(|e| format!("{}  {}  at={}", e.id, e.kind, e.at)).collect::<Vec<_>>().join("\n")
        }
    });
    Ok(())
}

fn cmd_sweep(args: &Args) -> Result<(), String> {
    let chan = bsc_appchan::chan_dir()?;
    let n = bsc_appchan::sweep_stale(&chan, bsc_util::now_ms(), args.max_age_ms.unwrap_or(STALE_MS))?;
    bsc_cli_util::emit(args.pretty, args.json, &serde_json::json!({ "removed": n }), || {
        format!("removed {n} stale file(s)")
    });
    Ok(())
}

fn cmd_dir(args: &Args) -> Result<(), String> {
    let shots = shots_dir()?;
    let chan = bsc_appchan::chan_dir()?;
    let v = serde_json::json!({ "shots": shots.display().to_string(), "channel": chan.display().to_string() });
    bsc_cli_util::emit(args.pretty, args.json, &v, || {
        format!("shots:   {}\nchannel: {}", shots.display(), chan.display())
    });
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A capture that CANNOT be analysed must still be reaped. This is the leftover nobody would ever
    /// notice, because the command that made it failed and no one reads that output.
    #[test]
    fn a_capture_that_fails_to_analyse_is_still_reaped() {
        let dir = tempfile::tempdir().unwrap();
        let bad = dir.path().join("not-really-a.png");
        std::fs::write(&bad, b"this is not a PNG").unwrap();
        let p = bad.to_string_lossy().into_owned();

        let err = analyze_captured(&p, false).unwrap_err();
        assert!(err.contains("not a decodable PNG"), "the real reason survives: {err}");
        assert!(!bad.exists(), "the unreadable capture was reaped anyway");
    }

    /// `--keep` opts out, and SAYS WHERE — a kept file the caller cannot find is not kept.
    #[test]
    fn keep_leaves_the_capture_and_reports_its_path() {
        let dir = tempfile::tempdir().unwrap();
        let bad = dir.path().join("kept.png");
        std::fs::write(&bad, b"nope").unwrap();
        let p = bad.to_string_lossy().into_owned();

        assert!(analyze_captured(&p, true).is_err());
        assert!(bad.exists(), "--keep survives even the failure path");
    }

    /// THE GUARD. `<shots>/baselines/` holds the named reference renders `diff` compares against — the
    /// one thing here that is not regenerable on demand. Eat one and every later diff reports a
    /// plausible number about nothing. A `--out` aimed into that directory must not become a delete.
    #[test]
    fn a_baseline_is_never_reaped_however_it_was_named() {
        let dir = tempfile::tempdir().unwrap();
        let baselines = dir.path().join("baselines");
        std::fs::create_dir_all(&baselines).unwrap();
        let saved = baselines.join("listitemcard.png");
        std::fs::write(&saved, b"reference").unwrap();

        assert!(!reap(&saved.to_string_lossy()), "refused");
        assert!(saved.exists(), "the reference render survives");

        // …while an ordinary capture beside it goes.
        let ordinary = dir.path().join("listitemcard.png");
        std::fs::write(&ordinary, b"capture").unwrap();
        assert!(reap(&ordinary.to_string_lossy()));
        assert!(!ordinary.exists());
    }

    /// A refused reap reports as KEPT, so the line never claims a file is gone while it is still there.
    #[test]
    fn a_refused_reap_is_reported_as_kept_not_as_reaped() {
        let dir = tempfile::tempdir().unwrap();
        let baselines = dir.path().join("baselines");
        std::fs::create_dir_all(&baselines).unwrap();
        let saved = baselines.join("card.png");
        std::fs::write(&saved, b"not a png either").unwrap();
        let p = saved.to_string_lossy().into_owned();

        // It fails to decode, but the point is the fate: refused ⇒ kept, and the path is named.
        assert!(analyze_captured(&p, false).is_err());
        assert!(saved.exists());
    }

    /// A `--file` is the caller's, and reading it must never delete it — nor even depend on `--keep`,
    /// which would imply this verb had considered it.
    #[test]
    fn a_supplied_file_is_read_and_never_reaped() {
        let dir = tempfile::tempdir().unwrap();
        let mine = dir.path().join("theirs.png");
        std::fs::write(&mine, b"not a png, but it is THEIRS").unwrap();
        let p = mine.to_string_lossy().into_owned();

        // `analyze_captured` is told `keep` for a supplied file — the decision cmd_analyze makes from
        // `ours`. Even on the failure path the file survives.
        assert!(analyze_captured(&p, true).is_err());
        assert!(mine.exists(), "a file we did not create is never deleted");
    }

    /// The three fates are worded apart on purpose: a capture we reaped, a capture we kept, and a file
    /// that was never ours.
    #[test]
    fn the_line_distinguishes_a_kept_capture_from_a_file_that_was_never_ours() {
        let f = crate::Frame { w: 8, h: 8, blank: false, colours: 3, background: [0, 0, 0], ink: 0.5, empty_tiles: 0, tiles: 64 };
        assert!(analyze_line(&f, "reaped").ends_with("reaped"));
        assert!(analyze_line(&f, "kept: /x.png").ends_with("kept: /x.png"));
        assert!(analyze_line(&f, "read: /x.png").ends_with("read: /x.png"));
    }

    /// `blank` leads the line, because it invalidates every other number on it.
    #[test]
    fn the_lean_line_leads_with_blank_and_states_the_captures_fate() {
        let blank = crate::Frame { w: 8, h: 8, blank: true, colours: 1, background: [0, 0, 0], ink: 0.0, empty_tiles: 64, tiles: 64 };
        let line = analyze_line(&blank, "reaped");
        assert!(line.starts_with("BLANK"), "the finding that matters comes first: {line}");
        assert!(line.ends_with("reaped"), "and the capture's fate is stated: {line}");

        let drawn = crate::Frame { w: 1280, h: 820, blank: false, colours: 4213, background: [10, 11, 13], ink: 0.621, empty_tiles: 6, tiles: 64 };
        let line = analyze_line(&drawn, "kept: /tmp/x.png");
        assert!(!line.contains("BLANK"));
        assert!(line.contains("1280x820") && line.contains("4213 colours"), "{line}");
        assert!(line.contains("#0a0b0d"), "the background is readable as a hex colour: {line}");
        assert!(line.contains("ink 62.1%") && line.contains("6/64 tiles empty"), "{line}");
        assert!(line.ends_with("kept: /tmp/x.png"), "a kept capture names where it landed: {line}");
    }

    #[test]
    fn parses_a_rect() {
        assert_eq!(parse_rect("1,2,3,4").unwrap(), Rect { x: 1, y: 2, w: 3, h: 4 });
        assert_eq!(parse_rect(" 10 , 20 , 30 , 40 ").unwrap(), Rect { x: 10, y: 20, w: 30, h: 40 });
    }

    #[test]
    fn rejects_a_rect_the_app_could_only_fail_on() {
        // Caught here so the caller learns WHAT was wrong; the app could only say "capture failed".
        assert!(parse_rect("1,2,3").is_err(), "needs 4 parts");
        assert!(parse_rect("1,2,3,4,5").is_err());
        assert!(parse_rect("a,2,3,4").is_err(), "non-numeric");
        assert!(parse_rect("-1,2,3,4").is_err(), "negative");
        assert!(parse_rect("1,2,0,4").is_err(), "zero width has no pixels");
        assert!(parse_rect("1,2,3,0").is_err(), "zero height has no pixels");
    }

    #[test]
    fn unknown_flags_are_rejected_rather_than_ignored() {
        assert!(parse_args(vec!["take".into(), "--nope".into()]).is_err());
    }

    #[test]
    fn flags_parse_off_the_positional() {
        let a = parse_args(vec![
            "take".into(),
            "--rect".into(),
            "1,2,3,4".into(),
            "--out".into(),
            "x.png".into(),
            "--timeout".into(),
            "50".into(),
            "--json".into(),
        ])
        .unwrap();
        assert_eq!(a.positional, vec!["take"]);
        assert_eq!(a.rect, Some(Rect { x: 1, y: 2, w: 3, h: 4 }));
        assert_eq!(a.out.as_deref(), Some("x.png"));
        assert_eq!(a.timeout_ms, Some(50));
        assert!(a.json);
    }

    #[test]
    fn parses_frames_and_interval() {
        let a = parse_args(vec![
            "take".into(), "--frames".into(), "6".into(), "--interval".into(), "80".into(),
        ])
        .unwrap();
        assert_eq!(a.frames, Some(6));
        assert_eq!(a.interval_ms, Some(80));
        // Absent ⇒ None; cmd_take defaults frames→1 and interval→DEFAULT_INTERVAL_MS.
        let bare = parse_args(vec!["take".into()]).unwrap();
        assert_eq!(bare.frames, None);
        assert_eq!(bare.interval_ms, None);
    }

    #[test]
    fn frames_and_interval_reject_non_numbers() {
        assert!(parse_args(vec!["take".into(), "--frames".into(), "lots".into()]).is_err());
        assert!(parse_args(vec!["take".into(), "--interval".into(), "fast".into()]).is_err());
    }

    #[test]
    fn insert_suffix_marks_the_frame() {
        // Inserted before a real extension (so the files stay sortable, and stay PNGs).
        assert_eq!(insert_suffix("anim.png", 1, 2), "anim-01.png");
        assert_eq!(insert_suffix("C:/shots/anim.png", 12, 2), "C:/shots/anim-12.png");
        // No extension ⇒ appended.
        assert_eq!(insert_suffix("anim", 3, 2), "anim-03");
        // A dot that belongs to a PARENT directory is not an extension — append, don't split the dir.
        assert_eq!(insert_suffix("C:/a.b/out", 4, 2), "C:/a.b/out-04");
        // Padding follows the requested width (the frame-count's digit count).
        assert_eq!(insert_suffix("f.png", 7, 3), "f-007.png");
    }

    #[test]
    fn preview_rejects_an_explicit_rect() {
        // `preview` crops to the component preview itself; --rect would be ambiguous, so it's a stated
        // error (returned BEFORE any channel I/O), not a silent no-op.
        let a = parse_args(vec!["preview".into(), "--rect".into(), "1,2,3,4".into()]).unwrap();
        assert!(cmd_preview(&a).is_err());
    }

    #[test]
    fn resolve_out_anchors_the_png_in_the_session_shots_dir() {
        let shots = std::path::Path::new(if cfg!(windows) { "C:\\ws\\design-studio\\shots" } else { "/ws/design-studio/shots" });
        // No --out ⇒ <shots>/<id>.png (the #3662 fix: the app used to default to its OWN global dir).
        let def = resolve_out(None, shots, "abc");
        assert!(def.contains("design-studio") && def.ends_with("abc.png"), "default lands in the session dir: {def}");
        // A relative --out ⇒ inside the shots dir, NOT left cwd-relative for the app to misplace.
        let rel = resolve_out(Some("frame.png"), shots, "abc");
        assert!(rel.contains("design-studio") && rel.ends_with("frame.png"), "got {rel}");
        assert_ne!(rel, "frame.png", "a relative --out must be anchored");
        // An absolute --out ⇒ honored as-is (the designer's known-good workaround stays valid).
        let abs = if cfg!(windows) { "C:\\elsewhere\\x.png" } else { "/elsewhere/x.png" };
        assert_eq!(resolve_out(Some(abs), shots, "abc"), abs);
    }

    /// A read-back failure to build a report from.
    fn nofile() -> std::io::Error {
        std::io::Error::new(std::io::ErrorKind::NotFound, "The system cannot find the file specified")
    }

    #[test]
    fn the_unreadable_report_names_every_input_that_decides_the_path() {
        // #4163: `the app reported <path> but it cannot be read: os error 2` named NONE of the state that
        // decides where the PNG went, so a designer session lost every screenshot with nothing to act on.
        let res = ShotResult {
            path: "C:/ws/design-studio/shots/x.png".into(),
            w: 1,
            h: 1,
            shots_dir: Some("C:/Users/k/.base-studio-code/shots".into()),
        };
        let msg = unreadable_report(&res, Some("C:/ws/design-studio/shots/x.png"), Some("C:/ws/design-studio/shots"), &nofile());
        // The four facts, all present.
        assert!(msg.contains("C:/ws/design-studio/shots/x.png"), "the reported path: {msg}");
        assert!(msg.contains("you asked for"), "what was requested: {msg}");
        assert!(msg.contains("your $BSC_SHOT_DIR"), "the caller's dir: {msg}");
        assert!(msg.contains("C:/Users/k/.base-studio-code/shots"), "the APP's dir: {msg}");
        assert!(msg.contains("cannot find the file"), "the underlying os error survives: {msg}");
    }

    #[test]
    fn the_unreadable_report_states_the_diagnosis_when_the_two_dirs_differ() {
        let res = ShotResult {
            path: "C:/app/shots/x.png".into(),
            w: 1,
            h: 1,
            shots_dir: Some("C:/app/shots".into()),
        };
        // Differing dirs ⇒ the app resolved its own; say so, and say what to do about it.
        let diverged = unreadable_report(&res, Some("C:/ws/shots/x.png"), Some("C:/ws/shots"), &nofile());
        assert!(diverged.contains("two dirs differ"), "{diverged}");
        assert!(diverged.contains("ABSOLUTE --out"), "it names the fix: {diverged}");

        // Matching dirs ⇒ the path is NOT the disagreement; sending the reader after it would be a false
        // trail, so the message rules it out instead.
        // Same dir, written the OTHER way — separator style must not read as a divergence.
        let agreed = unreadable_report(&res, Some("C:/app/shots/x.png"), Some(r"C:\app\shots\"), &nofile());
        assert!(agreed.contains("Both sides agree"), "{agreed}");
        assert!(!agreed.contains("two dirs differ"), "{agreed}");
    }

    #[test]
    fn the_unreadable_report_survives_an_older_app_and_an_unset_caller_dir() {
        // The CLI is routinely newer than the running app — the exact case being diagnosed. A missing
        // field must READ as missing (and date the app), never render as an empty dir that looks resolved.
        let legacy = ShotResult { path: "p.png".into(), w: 1, h: 1, shots_dir: None };
        let msg = unreadable_report(&legacy, None, None, &nofile());
        assert!(msg.contains("predates this field"), "an older app is named as such: {msg}");
        assert!(msg.contains("unset"), "an unset caller dir says so: {msg}");
        assert!(msg.contains("the app picks"), "a no---out request says what the app would choose: {msg}");
        // With nothing to compare, it must not assert a diagnosis either way.
        assert!(!msg.contains("two dirs differ") && !msg.contains("Both sides agree"), "{msg}");
    }

    #[test]
    fn same_dir_ignores_separator_style_and_a_trailing_slash() {
        // A textual compare would report these as a divergence and send the reader down a false trail.
        assert!(same_dir("C:/ws/shots", "C:\\ws\\shots"));
        assert!(same_dir("C:/ws/shots/", "C:/ws/shots"));
        assert!(same_dir("C:/WS/Shots", "c:/ws/shots"));
        assert!(!same_dir("C:/ws/shots", "C:/ws/other"));
    }

    #[test]
    fn a_baseline_lives_under_the_sessions_shots_dir_keyed_by_component() {
        // Under `<shots>/baselines/<id>.png` so `$BSC_SHOT_DIR` is honoured exactly as it is for every
        // other capture — a confined session must be able to READ what it wrote (#3662).
        let shots = std::path::Path::new("/tmp/shots");
        let p = baseline_path(shots, "settings-general");
        assert!(p.ends_with("baselines/settings-general.png"), "{}", p.display());
        assert!(p.starts_with(shots), "it stays inside the session's shots dir: {}", p.display());
    }

    #[test]
    fn diff_tells_a_component_id_from_a_file_path() {
        // The two-path form is the OLDER contract and must win any ambiguity: a real file is never
        // re-read as an id. So the id form is deliberately narrow — no extension, no separator.
        assert!(looks_like_a_path("before.png"));
        assert!(looks_like_a_path("shots/before.png"));
        assert!(looks_like_a_path(r"C:\shots\before.png"));
        assert!(!looks_like_a_path("settings-general"));
        assert!(!looks_like_a_path("ui-tab-bar"));
    }

    #[test]
    fn diff_by_id_refuses_when_no_baseline_was_ever_saved() {
        // A verdict against a baseline that does not exist would be a NUMBER ABOUT NOTHING — worse than
        // an error, because it looks like an answer. Say what is missing and how to make it.
        let dir = std::env::temp_dir().join(format!("bsc-shot-nobase-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        // SAFETY: single-threaded test process; the var is read by `shots_dir()` on the next line only.
        unsafe { std::env::set_var("BSC_SHOT_DIR", &dir) };

        let args = Args { positional: vec!["diff".into(), "never-captured".into()], ..Default::default() };
        let err = cmd_diff(&args).unwrap_err();
        assert!(err.contains("no baseline for 'never-captured'"), "{err}");
        assert!(err.contains("bsc shot baseline never-captured"), "it names the fix: {err}");
    }

    #[test]
    fn baseline_refuses_a_component_and_a_kit_together() {
        // Guessing which the caller meant would sweep the wrong set WITHOUT SAYING SO — the exact class
        // of silent-wrong-answer this whole feature exists to remove.
        let args = Args {
            positional: vec!["baseline".into(), "settings-general".into()],
            kit: Some("base-studio-code".into()),
            ..Default::default()
        };
        let err = cmd_baseline(&args).unwrap_err();
        assert!(err.contains("takes a component OR --kit, not both"), "{err}");
        assert!(err.contains("settings-general") && err.contains("base-studio-code"), "it names both: {err}");
    }

    #[test]
    fn a_sweep_report_names_every_skip_with_its_reason() {
        // The report IS the feature. A sweep that listed only successes leaves the designer trusting
        // baselines that were never taken — and a missing baseline surfaces later as a `diff` that
        // cannot run, or a comparison against a stale reference.
        let out = vec![
            SweepOutcome { id: "a".into(), status: "captured", reason: String::new() },
            SweepOutcome { id: "b".into(), status: "skipped", reason: "the app did not land it".into() },
            SweepOutcome { id: "c".into(), status: "captured", reason: String::new() },
        ];
        let json = serde_json::to_string(&out).unwrap();
        assert!(json.contains(r#""status":"skipped""#), "{json}");
        assert!(json.contains("the app did not land it"), "the reason rides the row: {json}");
        // A captured row carries no empty `reason` noise.
        assert!(!json.contains(r#""id":"a","status":"captured","reason""#), "{json}");
    }

    #[test]
    fn a_multiline_failure_collapses_to_one_line_per_component() {
        // The navigate timeout error is four lines of diagnosis. In a 45-row sweep that is a wall; the
        // detail stays reachable by re-running the one component.
        let e = "timed out after 8000ms waiting for the app to answer.
The request is at C:/x.
Is the desktop app running?";
        assert_eq!(first_line(e), "timed out after 8000ms waiting for the app to answer.");
    }
